  pipeline: [
    {t: "Create the project", d: "Name it, drop in a video (several clips join in order) or just a voiceover, write your first prompt, pick a style and a format, and add reference links if you want. Or press **Magic Edit** and BOSS decides everything."},
    {t: "Script", d: "Read the transcript word by word. Click a word to jump there, cut what you don't want, undo or redo. A voiceover-only project can generate its voiceover here."},
    {t: "Instructions", d: "Your first instruction, the project style, references and options. BOSS reads it before it starts."},
    {t: "Still frames first", d: "BOSS builds still frames of the graphics. **No video is rendered yet.** Click a frame and draw on it to leave a note."},
    {t: "Approve the frames", d: "Happy? Approve and BOSS renders the first draft. Drafts are always small and fast (940p, 24 fps)."},
    {t: "Editing", d: "Watch the draft, take a snapshot of any moment, write revision notes, then press **Render Draft**. You can also change the style or save the look as a new style."},
    {t: "Render the final", d: "When the draft is right, press **Render Final Version** for full resolution (1080p, 30 fps)."},
    {t: "Gallery", d: "Every rendered version, oldest to latest, so you can compare and go back to any of them."},
  ],

  cheat: [
    ['start', 'Sets up the editor and your style (first time only).'],
    ['edit this', 'Cuts a video dropped in `inbox/` using your Boss Style (`my-style.md`) and renders a draft to `outbox/`.'],
    ['use Kinetic Type', 'Builds in the orange-red typewriter + iris-wipe style (vertical).'],
    ['use Kinetic Type + Head Pop-Out', 'Same, with the presenter in a rounded box and her head popping out in some scenes.'],
    ['use Pastel Punch', 'The beige, navy and hot-pink carousel look.'],
    ['final', 'Renders the approved draft at full resolution (1080p, 30 fps).'],
    ['horizontal version', 'A 1920×1080 composition with its own framing, not just a crop.'],
    ['always … / never …', 'Saved as a lasting rule in `my-rules.md`.'],
  ],

  rules: [
    {t: "Huge slate words", d: "Orange section-break slates use HUGE text (235 to 400px), filling most of the frame, with a large number above.", quote: "\"make fonts Huge for these type of frames\""},
    {t: "Stills first, then drafts", d: "Show still frames first and do not render a video until you say so. Drafts render small and fast (940p, 24 fps); full resolution (1080p, 30 fps) only after you say \"final\".", quote: "\"dont render video yet\" · \"use 940p res first to run fast then we render in full res once final and I say so\""},
    {t: "No slide labels on vertical", d: "No top tag bars, section counters or tiny footnotes in Reels and Stories.", quote: "\"that's only good for slides presentation\""},
    {t: "Safe zone and centring", d: "Nothing in the lowest ~23% or top ~10%. All text centred.", quote: "\"this area should be left empty\""},
    {t: "No cut-off text", d: "Auto-fit or resize until text sits fully inside the frame with a margin.", quote: "\"make sure that no texts are cut out. resize when necessary\""},
    {t: "Card contrast", d: "White cards need a darker background, a visible border and a stronger shadow, so they never look over-exposed.", quote: "\"make sure there's contrast from the background\""},
    {t: "Readable on a phone", d: "Small items (pills, chips, nav links, labels) must be big enough to read on a phone. Short titles stay on one line and are sized to fit.", quote: "\"make about me one line so you can adjust sizing. and the small items under it make a bit bigger\""},
    {t: "Split layout", d: "The presenter sits in a wide rounded box near the bottom, head popping out above it, over an animated grid (dark and pale scenes).", quote: "\"it should look like this when you place the video at the bottom\""},
    {t: "B-roll for stories", d: "When she tells a story, show B-roll that follows it behind her instead of graphic illustrations. She stays in the speaker box and the B-roll fills the stage.", quote: "\"follow the story of what happen with broll instead of graphic illustrations\""},
    {t: "Sound design", d: "No whoosh or swish. Typing is a soft, deep, creamy keyboard thock kept under the voice, clicks are a normal mouse click, music is subtle corporate upbeat (never funk).", quote: "\"use a mechanical creamy sound. and lower the volume down\" · \"change to corporate upbeat\""},
    {t: "Clean voice", d: "No \"ah/uh\" fillers and no breath or mouth blips between words.", quote: "\"i can hear ah's .... fix that\""},
    {t: "Website mockups", d: "Use a generic business site with a text-free symbol logo. No people or profile placeholder images, no real company name as a logo.", quote: "\"make a simple logo, maybe just a symbolic logo... not a logo type\""},
    {t: "Easy style names", d: "Every style has a short name that says what it does (Kinetic Type, Pastel Punch, Hype Cam…). The older names still work when you say them.", quote: "\"i want this organize and self explanatory in terms of naming\""},
  ],

